JUDGE_AXES = [a for a in AXES if a["kind"] == "judge"]
SCRIPT_AXES = [a for a in AXES if a["kind"] == "script"]

def judge_batches():
    """Group judge axes into batches of one call each: by family, blind first."""
    batches = {}
    for a in JUDGE_AXES:
        key = a.get("batch") or f"{a['family']}_{'blind' if a['blind'] else 'open'}"
        if key == "derived": continue  # computed from another axis's evidence in analyze.py, never sent to a judge
        batches.setdefault(key, []).append(a)
    return batches

if __name__ == "__main__":
    from collections import Counter
    print(len(AXES), "axes;", len(JUDGE_AXES), "judge;", len(SCRIPT_AXES), "script")
    print(Counter(a["family"] for a in AXES))
    for k, v in judge_batches().items():
        print(f"  batch {k}: {len(v)} questions")
    ids = [a["id"] for a in AXES]; assert len(ids) == len(set(ids)), "duplicate ids"
